'use strict';
const http=require('node:http'),assert=require('node:assert/strict');
const {commercial,event,receipt,tick}=require('../helpers/audit-pending-fixtures.cjs');
async function trial(kind){
 if(kind==='foreground'){const f=commercial();f.c.page='page-dashboard';f.c.SVCommercialOwnership.onValue('ventas',()=>{});f.c.SVCommercialOwnership.onValue('presupuestos',()=>{});await tick();const initial=f.calls.length;f.c.page='page-productos';for(let i=0;i<5;i++)f.listeners.visibilitychange();await tick();const extra=f.calls.length-initial;f.c.page='page-dashboard';f.listeners['sisventas:page-changed']();await tick();assert.equal(extra,0);assert.equal(f.calls.length,4);return {title:'Sin consultas de historial al volver a Productos',values:[['Regresos simulados',5],['Consultas innecesarias',extra],['Actualizaciones al volver al Dashboard',2]]};}
 if(kind==='event'){const f=event({comisionHabilitada:false}),before=JSON.stringify(f.db.root);for(let i=0;i<5;i++)await f.api.handle({...f.req,headers:{...f.req.headers,'ce-id':'event-'+i}});assert.equal(JSON.stringify(f.db.root),before);assert.equal(f.phases.length,0);return {title:'Los eventos sin comisión no bloquean guardados',values:[['Eventos comprobados',5],['Bloqueos financieros',f.phases.length],['Escrituras',0]]};}
 if(kind==='receipt'){const f=receipt();f.abortSale();let pending=false;try{await f.c.finishReceipt(structuredClone(f.order),[f.movement()]);}catch(_){pending=true;}assert.ok(pending&&f.data['orders/o'].recepcionPendiente);assert.equal(f.notes.length,0);await f.c.finishReceipt(structuredClone(f.data['orders/o']),[]);assert.equal(f.data['inventory/p'].reservado,1);assert.equal(f.data['orders/o'].recepciones.length,1);return {title:'Recepción recuperada con un solo ingreso de stock',values:[['Unidades recibidas',1],['Unidades reservadas',f.data['inventory/p'].reservado],['Recepciones registradas',f.data['orders/o'].recepciones.length]]};}
 throw Error('Prueba no disponible');
}
const html=`<!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SisVentas · revisión final local</title><style>*{box-sizing:border-box}body{margin:0;background:#0b1321;color:#e7eefb;font:15px system-ui}header{padding:18px 5%;background:#101b2e;border-bottom:1px solid #30435c}main{max-width:1100px;margin:30px auto;padding:0 20px}h1{font-size:26px}h2{font-size:19px}p,small{color:#afbed3;line-height:1.5}.card{background:#142137;border:1px solid #344963;border-radius:16px;padding:22px;margin:18px 0}button{font:inherit;padding:11px 17px;background:#e8f0ff;color:#17253a;border:0;border-radius:9px;cursor:pointer}button:disabled{opacity:.6}.status{margin-top:16px;color:#a9dcb0}.metrics{display:flex;gap:25px;flex-wrap:wrap}.metrics b{display:block;font-size:25px;color:#8bd99a;padding-top:5px}.spin{display:inline-block;width:14px;height:14px;border:2px solid #385578;border-top-color:transparent;border-radius:50%;animation:spin .7s linear infinite;margin-right:8px}@keyframes spin{to{transform:rotate(360deg)}}button:focus-visible{outline:3px solid #8ab3f3;outline-offset:3px}@media(max-width:500px){.card{padding:16px}button{width:100%}}</style><header>SisVentas · pruebas locales con datos ficticios</header><main><h1>Circuitos de la revisión final</h1><p>Este ejemplo ejecuta los módulos reales con una base ficticia en memoria. No se conecta a tus cuentas, ventas ni stock.</p><section class="card"><h2>Regresar a otra ventana</h2><p>Productos conserva la vista sin releer ventas. Al volver al Dashboard, se actualiza el historial.</p><button data-kind="foreground">Probar regreso a Productos y Dashboard</button><p class="status" role="status"></p><div class="metrics"></div></section><section class="card"><h2>Evento de comisión sin efecto</h2><p>Una venta sin comisión habilitada no ocupa el guardado financiero.</p><button data-kind="event">Probar cinco eventos sin comisión</button><p class="status" role="status"></p><div class="metrics"></div></section><section class="card"><h2>Recepción interrumpida</h2><p>Si falla la confirmación, conserva el intento y permite recuperarlo sin repetir stock ni costo.</p><button data-kind="receipt">Interrumpir y recuperar una recepción</button><p class="status" role="status"></p><div class="metrics"></div></section><small>Resultados del ejemplo; no representan una medición de la factura de Google Cloud.</small></main><script>for(const b of document.querySelectorAll('button'))b.onclick=async()=>{const card=b.closest('section'),status=card.querySelector('.status'),out=card.querySelector('.metrics'),label=b.textContent;b.disabled=true;b.innerHTML='<span class="spin"></span>Comprobando…';try{const r=await fetch('/trial',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({kind:b.dataset.kind})}),v=await r.json();if(!r.ok)throw Error(v.error);status.textContent=v.title;out.replaceChildren();for(const [label,value]of v.values){const d=document.createElement('div'),s=document.createElement('small'),n=document.createElement('b');s.textContent=label;n.textContent=value;d.append(s,n);out.append(d);}}catch(e){status.textContent=e.message;}finally{b.disabled=false;b.textContent=label;}};</script></html>`;
async function start(port=0){const server=http.createServer(async(req,res)=>{try{if(req.method==='GET'&&req.url==='/'){res.writeHead(200,{'Content-Type':'text/html; charset=utf-8','Cache-Control':'no-store','Content-Security-Policy':"default-src 'none'; style-src 'unsafe-inline'; script-src 'unsafe-inline'; connect-src 'self'; frame-ancestors 'none'"});return res.end(html);}if(req.method==='POST'&&req.url==='/trial'){let body='';for await(const part of req){body+=part;if(body.length>256)throw Error('Pedido inválido');}const value=await trial(JSON.parse(body).kind);res.writeHead(200,{'Content-Type':'application/json'});return res.end(JSON.stringify(value));}res.writeHead(404);res.end();}catch(e){res.writeHead(400,{'Content-Type':'application/json'});res.end(JSON.stringify({error:e.message}));}});await new Promise(r=>server.listen(port,'127.0.0.1',r));return {server,url:'http://127.0.0.1:'+server.address().port+'/'};}
module.exports={start,trial};if(require.main===module)start(Number(process.argv[2]||8896)).then(x=>console.log(x.url));
